    AND sv.certification = 'CERTIFIED'


    AND s.owner_user_id = #{ownerUserId}


    AND (
        s.name ILIKE #{keywordPattern} ESCAPE '\'
        OR s.display_name ILIKE #{keywordPattern} ESCAPE '\'
        OR s.description ILIKE #{keywordPattern} ESCAPE '\'
        OR s.card_excerpt ILIKE #{keywordPattern} ESCAPE '\'
    )


    AND s.id IN (
        SELECT st.skill_id
        FROM skill_tag st
        WHERE st.tag_id IN

            #{tagId}

        GROUP BY st.skill_id
        HAVING count(*) = #{tagCount}
    )

mapper.select:
SELECT s.id AS id, s.name AS name, s.display_name AS display_name, s.card_excerpt AS card_excerpt,
s.status AS status, s.download_count AS download_count, s.like_count AS like_count, s.favorite_count AS favorite_count, s.updated_at AS updated_at, s.owner_user_id AS owner_user_id, ou.display_name AS owner_display_name, ou.employee_no AS owner_employee_no, s.declared_owner_name AS declared_owner_name, s.declared_owner_employee_no AS declared_owner_employee_no, sv.id AS latest_version_id, sv.version AS latest_version_version, sv.certification AS latest_version_certification FROM skill s LEFT JOIN app_user ou ON ou.id = s.owner_user_id LEFT JOIN skill_version sv ON sv.id = s.latest_version_id
ORDER BY ${sortColumn} DESC, s.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT st.skill_id AS skill_id, t.id AS tag_id, t.name AS tag_name, t.kind AS tag_kind, t.description AS tag_description, t.sort_order AS tag_sort_order, t.created_by_user_id AS tag_created_by_user_id, t.created_at AS tag_created_at, t.updated_at AS tag_updated_at FROM skill_tag st JOIN tag t ON t.id = st.tag_id WHERE st.skill_id IN
#{skillId}
ORDER BY st.skill_id, t.kind, t.sort_order, t.name

SELECT

FROM skill_version
WHERE skill_id = #{skillId} AND version = #{version}

SELECT artifact_key
FROM skill_version
WHERE id = #{versionId} AND skill_id = #{skillId}

mapper.update:
UPDATE skill s
SET latest_version_id = #{versionId},
    description = #{description},
    card_excerpt = #{cardExcerpt}
WHERE s.id = #{skillId}
  AND (
    s.latest_version_id IS NULL
    OR NOT EXISTS (
        SELECT 1 FROM skill_version cur
        WHERE cur.id = s.latest_version_id
          AND string_to_array(cur.version, '.')::int[] >= string_to_array(#{version}, '.')::int[]
    )
  )

UPDATE skill
SET owner_user_id = #{newOwnerUserId},
    updated_at    = now()
WHERE id = #{skillId}
  AND owner_user_id = #{systemUserId}

UPDATE skill_version
SET certification        = #{certification},
    certified_by_user_id = #{operatorUserId},
    certified_at         = now(),
    certify_note         = #{note}
WHERE id = #{versionId}

UPDATE skill
SET comment_count = GREATEST(comment_count + #{delta}, 0)
WHERE id = #{skillId}
